const data = $input.first().json;
const contacts = data.contacts || [];
const touchpoints = data.touchpoints || {};
const topics = (data.topics || []).reduce((acc, t) => { acc[t.id] = t.title; return acc; }, {});

// 強制鎖定台灣時區 (Asia/Taipei UTC+8)，徹底杜絕伺服器/Docker UTC 時差
const twDateStr = new Date().toLocaleString("en-US", { timeZone: "Asia/Taipei" });
const now = new Date(twDateStr);
const currentHour = now.getHours();
const pad = n => String(n).padStart(2, "0");
const timeStr = `${pad(currentHour)}:${pad(now.getMinutes())}`;

const STAGE_MAP = {
  'planned': '🟣 預計',
  'interaction': '🟡 互動',
  'pitched': '🔵 拋出',
  'agreed': '🟢 同意',
  'appointment': '🗓️ 約定',
  'in_progress': '🟠 洽談',
  'preparing': '🟣 籌劃',
  'considering': '💠 考慮',
  'closed': '🟢 完成',
  'paused': '⚪ 暫緩',
  'rejected': '🔴 婉拒',
  'referral': '🤝 轉介'
};

const getDaysDiff = (dateStr) => {
  if (!dateStr) return 999;
  const d = new Date(dateStr);
  if (isNaN(d.getTime())) return 999;
  return Math.floor((now - d) / (1000 * 60 * 60 * 24));
};

const getCooldownThreshold = (category) => {
  const cat = category || '';
  if (/董座|總經理|企業主|竹科|新貴|合夥/i.test(cat)) return 30;
  if (/親人|退休|一般緣故/i.test(cat)) return 90;
  return 60;
};

const items = contacts.map(c => {
  const cid = c.id;
  const isFoc = c.isFocused === true || c.isFocused === 'true' || c.isFocused === 'TRUE';
  const isCtrl = c.isControlled === true || c.isControlled === 'true' || c.isControlled === 'TRUE';
  const days = getDaysDiff(c.lastContactDate);
  const cooldownTarget = getCooldownThreshold(c.category);

  const list = Object.values(touchpoints).filter(v => v && v.contactId === cid && v.latestDate);
  list.sort((a, b) => new Date(b.latestDate) - new Date(a.latestDate));

  let stageLabel = '尚未定聯';
  let topicTitle = '無';
  let nextAction = '';
  let rawStatus = '';
  let isCooling = false;

  if (list.length > 0) {
    const top = list[0];
    rawStatus = top.status || '';
    stageLabel = STAGE_MAP[top.status] || top.status || '紀錄';
    topicTitle = topics[top.topicId] || '自選議題';

    if (rawStatus === 'closed' && days < cooldownTarget) {
      isCooling = true;
    }

    for (const h of (top.history || [])) {
      if (h.nextAction && h.nextAction.trim()) {
        nextAction = h.nextAction.trim();
        break;
      }
    }
  }

  if (!nextAction) {
    if (days >= 999) nextAction = '發起日常破冰關懷';
    else if (['appointment', 'in_progress'].includes(rawStatus)) nextAction = '準備會談說帖與試算表';
    else if (['pitched', 'considering'].includes(rawStatus)) nextAction = '追蹤反饋與痛點';
    else nextAction = '排定下次定聯話題';
  }

  return {
    name: c.name,
    category: c.category || '客戶',
    isFoc,
    isCtrl,
    days,
    stageLabel,
    topicTitle,
    rawStatus,
    nextAction,
    isCooling,
    cooldownTarget
  };
});

const activePool = items.filter(i => i.isCtrl || i.isFoc || !i.isCooling);

let timeSlotTitle = '';
let pushList = [];

if (currentHour >= 6 && currentHour <= 9) {
  timeSlotTitle = '🌅 晨間戰略 Focus';
  const focusItems = activePool.filter(i => i.isCtrl || i.isFoc).slice(0, 2);
  const appointments = activePool.filter(i => !i.isCtrl && !i.isFoc && ['appointment', 'in_progress'].includes(i.rawStatus)).slice(0, 2);
  pushList = [...focusItems, ...appointments].slice(0, 3);
  if (pushList.length === 0) pushList = activePool.slice(0, 2);
} else if (currentHour >= 10 && currentHour <= 17) {
  timeSlotTitle = '⚡ 白天行動推進';
  const focusItems = activePool.filter(i => i.isCtrl || i.isFoc).slice(0, 1);
  const inProgress = activePool.filter(i => !i.isCtrl && !i.isFoc && ['appointment', 'in_progress', 'pitched', 'preparing'].includes(i.rawStatus)).slice(0, 2);
  pushList = [...focusItems, ...inProgress].slice(0, 3);
  if (pushList.length === 0) pushList = activePool.slice(0, 2);
} else {
  timeSlotTitle = '🌙 晚間破冰關懷';
  const overdue = activePool.filter(i => !i.isCtrl && !i.isFoc && i.days >= i.cooldownTarget)
    .sort((a, b) => b.days - a.days)
    .slice(0, 2);
  const focusItems = activePool.filter(i => i.isCtrl || i.isFoc).slice(0, 1);
  pushList = [...focusItems, ...overdue].slice(0, 3);
  if (pushList.length === 0) pushList = activePool.slice(0, 2);
}

let msg = `<b>${timeSlotTitle} (${timeStr})</b>\n\n`;

pushList.forEach(item => {
  const tag = item.isCtrl ? '🚨 ' : (item.isFoc ? '⭐ ' : (['appointment', 'in_progress'].includes(item.rawStatus) ? '🔥 ' : '💬 '));
  const dayDesc = item.days >= 999 ? '久未聯' : `${item.days}天`;
  msg += `${tag}<b>${item.name}</b> (${dayDesc})\n`;
  msg += `  ├ <b>推進階段</b>：${item.stageLabel}\n`;
  msg += `  ├ <b>連結議題</b>：【${item.topicTitle}】\n`;
  msg += `  └ <b>行動指令</b>：${item.nextAction.slice(0, 24)}\n\n`;
});

msg += `👉 <a href="http://localhost:5678">打開畫布推進</a>`;

return [{ json: { messageText: msg } }];
